implementation:
AP4_HdlrAtom::AP4_HdlrAtom(AP4_UI32 size, AP4_UI08 version, AP4_UI32 flags, AP4_ByteStream& stream) : AP4_Atom(AP4_ATOM_TYPE_HDLR, size, version, flags) {
    // Read the predefined values (4 bytes of zeros)
    AP4_UI32 predefined;
    stream.ReadBE(&predefined, sizeof(predefined));

    // Read the handler type (4 bytes)
    stream.ReadBE(&m_HandlerType, sizeof(m_HandlerType));

    // Read the reserved bytes (2 bytes)
    AP4_UI16 reserved;
    stream.ReadBE(&reserved, sizeof(reserved));

    // Determine how much space is left for the handler name
    AP4_UI32 name_size = m_Size - (stream.Tell() - stream.GetStart());

    // Read the handler name if there is space
    if (name_size > 0) {
        m_HandlerName = new AP4_UI08[name_size];
        AP4_UI08* name = m_HandlerName;
        AP4_Size bytesRead = 0;

        // Read the handler name
        stream.ReadBE(name, name_size);

        // Handle Pascal string format (if first byte is 0x00)
        if (name_size > 1 && name[0] == 0x00) {
            AP4_UI08* newName = new AP4_UI08[name_size];
            AP4_CopyMemory(newName, name + 1, name_size - 1);
            newName[name_size - 1] = 0x00; // Ensure null termination
            delete[] name;
            m_HandlerName = newName;
        }
        // Handle C string format
        else {
            // Ensure null termination
            m_HandlerName[name_size - 1] = 0x00;
        }
    }
}
